import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Modernizing Ceph Deployments at CERN- CephFS and Object Storage Across Data Centres - Enrico Bocchi","description":"","frontmatter":{"title":"Modernizing Ceph Deployments at CERN- CephFS and Object Storage Across Data Centres - Enrico Bocchi","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-19T00:00:00.000Z","tags":["CephFS","Ceph 存储升级","分布式存储","跨数据中心存储","CERN"],"categories":["存储技术","Ceph","数据中心","会议总结","存储架构"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Modernizing_Ceph_Deployments_at_CERN_-_CephFS_and_Object_Storage_Across_Data_Centres_-_Enrico_Bocchi.md","filePath":"posts/2025/Modernizing_Ceph_Deployments_at_CERN_-_CephFS_and_Object_Storage_Across_Data_Centres_-_Enrico_Bocchi.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Modernizing_Ceph_Deployments_at_CERN_-_CephFS_and_Object_Storage_Across_Data_Centres_-_Enrico_Bocchi.md"};function r(n,l,s,h,_,p){return e(),a("div",null,[...l[0]||(l[0]=[t('<h2 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h2><ul><li><strong>演讲者</strong>：Enrico（CERN SEF 技术负责人）</li><li><strong>会议主题</strong>：CERN 中 Ceph 存储部署的现代化升级方案</li><li><strong>主要内容</strong>：聚焦 CephFS 优化、多文件系统部署、跨数据中心存储方案</li></ul><h2 id="核心讨论内容" tabindex="-1">核心讨论内容 <a class="header-anchor" href="#核心讨论内容" aria-label="Permalink to &quot;核心讨论内容&quot;">​</a></h2><h3 id="_1-ceph-在-cern-的现状" tabindex="-1">1. Ceph 在 CERN 的现状 <a class="header-anchor" href="#_1-ceph-在-cern-的现状" aria-label="Permalink to &quot;1. Ceph 在 CERN 的现状&quot;">​</a></h3><ul><li><strong>部署规模</strong>：20个生产集群，约100PB容量，分布在3个不同位置</li><li><strong>主要用例</strong>： <ul><li>Kubernetes/OpenShift PVC 后端存储</li><li>HPC 暂存和临时空间</li><li>软件编译和分发（RPM）</li><li>替代 Windows DFS（SEFS+SMB 原型）</li><li>新型 home 目录服务（SEFS over NFS）</li></ul></li></ul><h3 id="_2-cephfs-运营挑战" tabindex="-1">2. CephFS 运营挑战 <a class="header-anchor" href="#_2-cephfs-运营挑战" aria-label="Permalink to &quot;2. CephFS 运营挑战&quot;">​</a></h3><ul><li><strong>关键问题</strong>： <ul><li>缺乏客户端 metadata 请求限流机制</li><li>高并发目录操作导致的性能问题</li><li>MDS 崩溃风险（特别是驱逐客户端时）</li><li>备份方案不足（未使用 snapshots）</li></ul></li></ul><h3 id="_3-现代化部署方案" tabindex="-1">3. 现代化部署方案 <a class="header-anchor" href="#_3-现代化部署方案" aria-label="Permalink to &quot;3. 现代化部署方案&quot;">​</a></h3><ul><li><p><strong>架构优化方向</strong>：</p><ul><li>从大型单一文件系统转向专用文件系统</li><li>通过 OpenStack Manila share types 实现隔离</li><li>构建 availability zones 实现跨数据中心冗余</li></ul></li><li><p><strong>技术实现</strong>：</p><ul><li>同集群部署多个文件系统</li><li>每个文件系统配置独立 MDS</li><li>与 Kubernetes CSI 深度集成</li></ul></li></ul><h3 id="_4-多文件系统运营经验" tabindex="-1">4. 多文件系统运营经验 <a class="header-anchor" href="#_4-多文件系统运营经验" aria-label="Permalink to &quot;4. 多文件系统运营经验&quot;">​</a></h3><ul><li><p><strong>优势</strong>：</p><ul><li>更好的隔离性和可控性</li><li>独立配置调优</li><li>滚动升级可能性</li></ul></li><li><p><strong>灾备注意事项</strong>：</p><ul><li>默认文件系统恢复顺序问题</li><li>推荐客户端明确指定文件系统名挂载</li></ul></li></ul><h3 id="_5-metadata-负载均衡测试" tabindex="-1">5. Metadata 负载均衡测试 <a class="header-anchor" href="#_5-metadata-负载均衡测试" aria-label="Permalink to &quot;5. Metadata 负载均衡测试&quot;">​</a></h3><ul><li><p><strong>测试方法</strong>：</p><ul><li>基于 IO500 MDtest 基准</li><li>对比不同策略：自动平衡、手动 pinning、ephemeral pinning</li></ul></li><li><p><strong>主要发现</strong>：</p><ul><li>自动平衡器在高负载时性能下降</li><li>手动 pinning 提供最佳控制但需管理员介入</li><li>Ephemeral pinning 策略效果因工作负载而异</li></ul></li></ul><h3 id="_6-跨数据中心方案" tabindex="-1">6. 跨数据中心方案 <a class="header-anchor" href="#_6-跨数据中心方案" aria-label="Permalink to &quot;6. 跨数据中心方案&quot;">​</a></h3><ul><li><p><strong>CephFS 跨 DC</strong>：</p><ul><li>通过 CRUSH rule 确保每个 DC 有数据副本</li><li>利用 MDS join FS tag 实现&quot;偏好&quot;数据中心</li><li>客户端本地读优化待完善</li></ul></li><li><p><strong>对象存储跨 DC</strong>：</p><ul><li>传统多站点配置（primary+secondary）</li><li>通过前端负载均衡器实现透明访问</li><li>利用新增 HTTP headers 检查复制状态</li></ul></li></ul><h2 id="未来工作计划" tabindex="-1">未来工作计划 <a class="header-anchor" href="#未来工作计划" aria-label="Permalink to &quot;未来工作计划&quot;">​</a></h2><ol><li><p><strong>对象存储整合</strong>：</p><ul><li>统一管理三个对象存储集群</li><li>开发自动化数据迁移工作流</li></ul></li><li><p><strong>备份增强</strong>：</p><ul><li>与磁带存储系统集成</li><li>评估 RGW zipper 提供 S3-to-POSIX 接口</li></ul></li><li><p><strong>客户端优化</strong>：</p><ul><li>完善跨 DC 读取本地性</li><li>改进 metadata 限流机制</li></ul></li></ol><h2 id="问答环节重点" tabindex="-1">问答环节重点 <a class="header-anchor" href="#问答环节重点" aria-label="Permalink to &quot;问答环节重点&quot;">​</a></h2><ol><li><p><strong>灾备故障转移</strong>：</p><ul><li>当前采用手动切换模式，secondary 集群保持 read-only</li><li>确保强一致性，避免数据丢失</li></ul></li><li><p><strong>备份方案</strong>：</p><ul><li>当前备份目标为专用 HDD 集群或磁带系统</li><li>未来计划实现更统一的备份接口</li></ul></li></ol><h2 id="行动项" tabindex="-1">行动项 <a class="header-anchor" href="#行动项" aria-label="Permalink to &quot;行动项&quot;">​</a></h2><ol><li>评估 S3 到磁带的工作流自动化方案</li><li>完善跨数据中心读取的客户端配置</li><li>推进多文件系统在生产环境的进一步部署</li></ol><p>[改进后的中文总结内容结束]</p>',22)])])}const d=i(o,[["render",r]]);export{c as __pageData,d as default};
